SELECT CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, o.channel, MAX(p.amount) AS max_amount, SUM(CASE WHEN p.status = 'SUCCESS' THEN p.amount ELSE 0 END) AS success_amount FROM payments p INNER JOIN orders o ON p.order_id = o.id GROUP BY CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END, o.channel HAVING success_amount > 21 ORDER BY max_amount DESC, order_cohort, channel LIMIT 3;
